const TOEIC_QUIZ = (() => {
  const PERMS3 = [
    [0, 1, 2], [0, 2, 1], [1, 0, 2],
    [1, 2, 0], [2, 0, 1], [2, 1, 0],
  ];
  return RAW_TOEIC_QUIZ.map(([tag, q, choices, ans, why], i) => {
    const set = (i % 20) + 1;
    const rankInSet = Math.floor(i / 20);
    const targetPos = (rankInSet + set * 3) % 4;
    const wrong = choices.filter((_, idx) => idx !== ans);
    const p = PERMS3[(i * 7 + rankInSet) % 6];
    const ordered = [null, null, null, null];
    ordered[targetPos] = choices[ans];
    let wi = 0;
    for (let pos = 0; pos < 4; pos++) {
      if (pos !== targetPos) ordered[pos] = wrong[p[wi++]];
    }
    return {
      id: 'tq' + String(i + 1).padStart(4, '0'),
      set,
      tag,
      q,
      choices: ordered,
      ans: targetPos,
      why,
    };
  });
})();

if (typeof module !== 'undefined') module.exports = { TOEIC_QUIZ };
